  const ambienceLabels={off:'Desligado',quiet_room:'Sala silenciosa',exodo_archive:'Êxodo · Arquivo Nexo',exodo_biolab:'Êxodo · Laboratório biométrico',exodo_industrial:'Êxodo · Complexo industrial',exodo_city_rain:'Êxodo · Megacidade sob chuva',ocultatun_archive:'Ocultatun · Arquivo interdito',ocultatun_ritual:'Ocultatun · Câmara ritual',ocultatun_anomaly:'Ocultatun · Anomalia ativa',ocultatun_subterranean:'Ocultatun · Subsolo inundado',forest_night:'Floresta noturna',storm:'Tempestade',fire_ruins:'Ruínas em chamas',custom:'Áudio importado'};
