    p.querySelector('[data-ga-terrain]').onchange=e=>{state.toolOptions.terrainType=e.target.value;persistSoon()};p.querySelector('[data-ga-fogmode]').onchange=e=>{state.toolOptions.fogMode=e.target.value;persistSoon()};p.querySelector('[data-ga-light-radius]').onchange=e=>{state.toolOptions.lightRadius=clamp(e.target.value,1,30,4);persistSoon()};p.querySelector('[data-ga-light-color]').onchange=e=>{state.toolOptions.lightColor=e.target.value;persistSoon()};p.querySelector('[data-ga-interactive]').onchange=e=>{state.toolOptions.interactiveType=e.target.value;persistSoon()};
