  function updatePanel(){const p=runtime.panel;if(!p)return;p.querySelectorAll('[data-ga-tool]').forEach(b=>b.classList.toggle('active',b.dataset.gaTool===runtime.tool));p.querySelector('[data-ga-dark]').checked=state.darkness.enabled;p.querySelector('[data-ga-darkop]').value=state.darkness.opacity;p.querySelector('[data-ga-terrain]').value=state.toolOptions.terrainType;p.querySelector('[data-ga-fogmode]').value=state.toolOptions.fogMode;p.querySelector('[data-ga-light-radius]').value=state.toolOptions.lightRadius;p.querySelector('[data-ga-light-color]').value=state.toolOptions.lightColor||'#ffd38a';p.querySelector('[data-ga-interactive]').value=state.toolOptions.interactiveType||'clue';p.querySelector('[data-ga-a1]').value=state.ambience.preset;p.querySelector('[data-ga-a2]').value=state.ambience.preset2;p.querySelector('[data-ga-v1]').value=state.ambience.volume;p.querySelector('[data-ga-v2]').value=state.ambience.volume2;p.querySelectorAll('[data-ga-fx]').forEach(el=>el.checked=!!state.effects[el.dataset.gaFx]);p.querySelector('[data-ga-fx-intensity]').value=state.effects.intensity;syncAmbientPanel();const ps=p.querySelector('[data-ga-placement-status]');if(ps){ps.hidden=!runtime.placementStatus;ps.textContent=runtime.placementStatus||''}
    const env=p.querySelector('[data-ga-env]');if(env&&catalogs.ready&&env.options.length<=1)env.insertAdjacentHTML('beforeend',catalogs.environments.map(o=>`<option value="${o.id}">${o.name}</option>`).join(''));
    const status=p.querySelector('[data-ga-library-status]');if(status)status.textContent=catalogs.ready?`${catalogs.environments.length} ambientes · ${catalogs.props.length} objetos · ${catalogs.tokens.length} totens`:'Biblioteca ainda não carregada.';
    if(catalogs.ready){const q=(p.querySelector('[data-ga-library-search]')?.value||'').trim().toLowerCase(),u=p.querySelector('[data-ga-library-universe]')?.value||'all',cat=p.querySelector('[data-ga-library-category]')?.value||'all';const matches=(o,kind)=>{if(u!=='all'&&o.universe!==u&&o.universe!=='generic')return false;if(cat!=='all'){if(cat==='environment'&&kind!=='environment')return false;if(cat==='token'&&kind!=='token')return false;if(!['environment','token'].includes(cat)&&(kind!=='prop'||o.category!==cat))return false}if(!q)return true;return [o.name,o.description,o.role,o.category,o.kind,o.scope,o.region,...(o.tags||[])].filter(Boolean).join(' ').toLowerCase().includes(q)};const sig=[q,u,cat].join('|');
      const gallery=p.querySelector('[data-ga-env-gallery]');if(gallery&&gallery.dataset.signature!==sig){gallery.dataset.signature=sig;gallery.innerHTML=catalogs.environments.map((o,i)=>matches(o,'environment')?`<button data-ga-env-card="${i}" title="${o.name}"><img loading="lazy" decoding="async" src="${o.thumbnail||o.file}" alt=""><span>${o.name}</span></button>`:'').join('')||'<em>Nenhum ambiente encontrado.</em>';gallery.querySelectorAll('[data-ga-env-card]').forEach(b=>b.onclick=()=>{const o=catalogs.environments[+b.dataset.gaEnvCard];setMap(o.file,o.width||1024,o.height||1024,o.name);p.querySelector('[data-ga-env]').value=o.id;if(state.ambience.preset==='off')state.ambience.preset=o.universe==='ocultatun'?'ocultatun_archive':'exodo_archive';persist({broadcast:true});updatePanel()})}
      const lib=p.querySelector('[data-ga-props]');if(lib&&lib.dataset.signature!==sig){lib.dataset.signature=sig;lib.innerHTML=catalogs.props.map((o,i)=>matches(o,'prop')?`<button data-ga-prop="${i}" title="${o.description||''}"><img loading="lazy" decoding="async" src="${o.thumbnail||o.file}" alt=""><span>${o.name}</span></button>`:'').join('')||'<em>Nenhum objeto encontrado.</em>';lib.querySelectorAll('[data-ga-prop]').forEach(b=>b.onclick=()=>queueProp(catalogs.props[+b.dataset.gaProp]))}
      const tok=p.querySelector('[data-ga-tokens]');if(tok&&tok.dataset.signature!==sig){tok.dataset.signature=sig;tok.innerHTML=catalogs.tokens.map((o,i)=>matches(o,'token')?`<button data-ga-token="${i}"><img loading="lazy" decoding="async" src="${o.thumbnail||o.file}" alt=""><span>${o.name}</span></button>`:'').join('')||'<em>Nenhum totem encontrado.</em>';tok.querySelectorAll('[data-ga-token]').forEach(b=>b.onclick=()=>spawnCatalogToken(catalogs.tokens[+b.dataset.gaToken]))}}
  }
  function openPanel(){if(!gm()){window.MS_PLATFORM?.toast?.('Somente o Mestre usa o Architect.','error');return false}const p=makePanel();p.hidden=false;if(!p.style.left){p.style.left=Math.max(8,innerWidth-p.offsetWidth-18)+'px';p.style.top='90px'}updatePanel();loadCatalogs().then(updatePanel).catch(()=>{});return true}
